fn main() {
    let add = |a: i32, b: i32| -> i32 { a + b };   // fully written out
    let add2 = |a, b| a + b;                         // types inferred
    let hello = || println!("hello");                // no arguments
    println!("{} {}", add(1, 2), add2(3, 4));
    hello();

    let factor = 3;
    let scale = |x| x * factor;                      // captures `factor`
    println!("{}", scale(5));                        // 15
}

fn main() {
    let id = |x| x;
    id(5);         // now id is i32 -> i32
