}

fn main() {
    let name = String::from("Ada");
    let greet = || println!("hi {name}");   // borrows name
    greet();
    greet();
    println!("{name}");                     // still usable

    let mut count = 0;
    let mut inc = || count += 1;            // mutably borrows count — note `let mut inc`
    inc();
    inc();
    println!("{count}");                    // 2
}

